<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
interface Job { id: string; status: 'pending' | 'handoff' | 'running' | 'restarting' | 'succeeded' | 'failed'; message?: string; error?: string }
interface Update { current_version: string; check_enabled: boolean; checked_at: string; check_error: string; update_available: boolean; release: { version: string; url: string; notes?: string } | null; installation: { mode: string; automatic_update: boolean; command: string; reason: string }; launcher_managed: boolean; is_admin: boolean; job: Job | null }
const update = ref<Update | null>(null)
const loading = ref(true)
const checking = ref(false)
const requesting = ref(false)
const confirmOpen = ref(false)
const error = ref('')
let timer: ReturnType<typeof setInterval> | undefined
const currentVersion = computed(() => update.value?.current_version || '—')
const activeJob = computed(() => Boolean(update.value?.job && ['pending', 'handoff', 'running', 'restarting'].includes(update.value.job.status)))
const canUpdate = computed(() => Boolean(update.value?.update_available && update.value.release && update.value.is_admin && update.value.launcher_managed && update.value.installation.automatic_update && !activeJob.value))
const installLabel = computed(() => ({ pypi: 'PyPI 安装包', source: '源码目录', docker: 'Docker 容器', unknown: '未知安装方式' } as Record<string, string>)[update.value?.installation.mode || 'unknown'])
async function load() { error.value = ''; try { update.value = await api<Update>('/api/system/update'); error.value = update.value.check_error || ''; watchJob() } catch (cause) { error.value = cause instanceof Error ? cause.message : '版本信息加载失败' } finally { loading.value = false } }
function watchJob() { if (timer) clearInterval(timer); if (!activeJob.value) return; timer = setInterval(async () => { try { const job = await api<Job | null>('/api/system/update/job'); if (update.value) update.value.job = job; if (!activeJob.value) { if (timer) clearInterval(timer); timer = undefined; if (job?.status === 'succeeded') await load() } } catch { /* The launcher may restart during an update. */ } }, 800) }
async function check() { checking.value = true; error.value = ''; try { update.value = await post<Update>('/api/system/update/check', {}); watchJob() } catch (cause) { error.value = cause instanceof Error ? cause.message : '检查更新失败' } finally { checking.value = false } }
async function toggleChecks() { if (!update.value) return; try { update.value = await api<Update>('/api/system/update/settings', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: update.value.check_enabled }) }) } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存更新设置失败' } }
async function requestUpdate() { requesting.value = true; error.value = ''; try { const job = await post<Job>('/api/system/update', { confirmation: 'update-and-restart' }); if (update.value) update.value.job = job; confirmOpen.value = false; watchJob() } catch (cause) { error.value = cause instanceof Error ? cause.message : '更新请求失败' } finally { requesting.value = false } }
load(); onUnmounted(() => { if (timer) clearInterval(timer) })
</script>
<template><div><header class="legacy-settings-page-header"><h1>关于</h1><p>DeepTutor 版本、发布渠道，以及当前安装最安全的更新方式。</p></header><p v-if="loading" class="legacy-settings-loading">加载中…</p><template v-else-if="update"><section class="about-version"><div><small>● 当前运行版本</small><strong>{{ currentVersion }}</strong></div><div><a v-if="update.release?.url" :href="update.release.url" target="_blank" rel="noopener noreferrer">发布说明 ↗</a><button v-if="update.is_admin" :disabled="checking || activeJob || !update.check_enabled" @click="check"><LegacyIcon name="history" :size="14" />{{ checking ? '正在检查…' : '立即检查' }}</button><button v-if="canUpdate" class="primary" @click="confirmOpen = true">更新到 {{ update.release?.version }}</button></div></section><p v-if="error" class="error" role="alert">{{ error }}</p><section class="legacy-setting-section"><h2>软件</h2><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>当前版本</h3></div><code>{{ currentVersion }}</code></div><div class="legacy-setting-row"><div><h3>安装方式</h3><p>{{ update.installation.reason }}</p></div><span>{{ installLabel }}</span></div><div class="legacy-setting-row"><div><h3>发布渠道</h3><p>仅考虑稳定发布的 DeepTutor 版本。</p></div><span>稳定版</span></div></div></section><section class="legacy-setting-section"><header><h2>更新</h2><p>版本检查缓存 24 小时。未经确认，DeepTutor 不会安装更新。</p></header><div class="legacy-setting-section-body"><div class="legacy-setting-row"><div><h3>检查更新</h3><p>离线或受控部署可关闭自动检查。</p></div><button role="switch" aria-label="检查更新" :aria-checked="update.check_enabled" class="legacy-toggle" :class="{ on: update.check_enabled }" @click="update.check_enabled = !update.check_enabled; toggleChecks()"><span /></button></div><div class="legacy-setting-row"><div><h3>最近检查</h3><p>{{ update.checked_at || '尚未检查' }}</p></div><span>{{ update.update_available ? `发现 ${update.release?.version}` : '已是最新版本' }}</span></div></div></section><section v-if="update.job" class="about-job" :class="update.job.status"><h2>更新任务</h2><p>{{ update.job.message || update.job.error || update.job.status }}</p></section><section class="legacy-setting-section"><h2>项目资源</h2><div class="legacy-setting-section-body legacy-setting-links"><a href="https://github.com/HKUDS/DeepTutor" target="_blank" rel="noopener noreferrer"><div><h3>源代码</h3><p>源代码、问题反馈与参与贡献。</p></div><LegacyIcon name="chevronRight" :size="16" /></a><a href="https://docs.deeptutor.info" target="_blank" rel="noopener noreferrer"><div><h3>文档</h3><p>DeepTutor 官方文档。</p></div><LegacyIcon name="chevronRight" :size="16" /></a></div></section></template><div v-if="confirmOpen" class="admin-dialog-overlay" @click.self="confirmOpen = false"><section class="admin-dialog admin-confirm-dialog" role="alertdialog" aria-modal="true" aria-label="确认更新"><header><h2>更新并重启？</h2><button aria-label="关闭" @click="confirmOpen = false">×</button></header><p>将更新到 {{ update?.release?.version }} 并重启 DeepTutor。进行中的对话可能中断，请先保存工作。</p><footer><button @click="confirmOpen = false">取消</button><button class="primary" :disabled="requesting" @click="requestUpdate">{{ requesting ? '正在请求…' : '更新并重启' }}</button></footer></section></div></div></template>
